"use client";
// "What this means for you" — the coaching insight card. Sits between the
// bell curve chart and the share/compare buttons in PersonalizedResult.tsx.
// All narrative content is generated by lib/insightMessages.ts; this
// component only renders it (tone -> accent color, paragraphs, source note,
// disclaimer) and never invents its own copy.
import type { CoachingInsight } from "@/lib/insightMessages";

const TONE_ACCENT: Record<CoachingInsight["tone"], string> = {
  strong: "#FBBF24",
  steady: "#34D399",
  building: "#34D399",
};

export default function CoachingInsightCard({
  insight,
  title,
  gapNote,
}: {
  insight: CoachingInsight;
  title: string;
  // The percentile-gap line ("save $X more to reach the top Y%") — computed
  // from real percentileAnchors data for whichever geography level is on
  // screen (see lib/percentileTable.ts's getNextPercentileGap). Optional and
  // rendered separately from `insight` so lib/insightMessages.ts's own
  // narrative logic stays untouched.
  gapNote?: string | null;
}) {
  const accent = TONE_ACCENT[insight.tone];
  return (
    <div className="mb-8 rounded-xl border border-white/10 bg-white/[0.02] p-5">
      <h2 className="mb-1 text-[13px] font-semibold text-white/50">{title}</h2>
      <p className="mb-3 text-[16px] font-bold leading-snug text-balance" style={{ color: accent }}>
        {insight.headline}
      </p>
      {gapNote && (
        <p className="mb-3 rounded-lg border border-[#FBBF24]/25 bg-[#FBBF24]/10 px-3 py-2 text-[13px] font-semibold leading-snug text-[#FBBF24]">
          {gapNote}
        </p>
      )}
      <div className="flex flex-col gap-2.5">
        {insight.paragraphs.map((p, i) => (
          <p key={i} className="text-[13px] leading-relaxed text-white/75">
            {p}
          </p>
        ))}
      </div>
      <div className="mt-4 border-t border-white/[0.06] pt-3">
        <p className="text-[10.5px] leading-relaxed text-white/30">{insight.sourceNote}</p>
        <p className="mt-1 text-[10.5px] leading-relaxed text-white/25">{insight.disclaimer}</p>
      </div>
    </div>
  );
}
